let client = new bacnet.default({
    apduTimeout: 2000,
    broadcastAddress: flow.get('ipBroadcast'),
    port: 47808,
});

/* clear console */
msg.payload = [];
node.send(msg);

client.on('error', (err) => {
    node.error('Erreur client: ' + err.message);
    client.close();
});

let address;

/* OBJECT TYPE */
let objectType = flow.get('objectType');

switch (objectType) {
    case "ANALOG_VALUE":
        objectType = bacnet.ObjectType.ANALOG_VALUE;
        break;

    case "ANALOG_INPUT":
        objectType = bacnet.ObjectType.ANALOG_INPUT;
        break;

    case "ANALOG_OUTPUT":
        objectType = bacnet.ObjectType.ANALOG_OUTPUT;
        break;

    case "BINARY_VALUE":
        objectType = bacnet.ObjectType.BINARY_VALUE;
        break;

    case "BINARY_INPUT":
        objectType = bacnet.ObjectType.BINARY_INPUT;
        break;

    case "BINARY_OUTPUT":
        objectType = bacnet.ObjectType.BINARY_OUTPUT;
        break;
}

/* TARGET INSTANCES */
const targetInstances = flow.get('targetInstances');
const targetInstancesString = JSON.stringify(targetInstances, null, 2);

let targetInstancesArray = [];
let j = 0;

/* ugly but works */
for (let i = 0; i < targetInstancesString.length; i++) {
    targetInstancesArray[i] = 0;
}

for (let i = 1; i < targetInstancesString.length - 1; i++) {

    if (targetInstancesString[i] === ',') {
        j++;
    }
    else {
        targetInstancesArray[j] *= 10;
        targetInstancesArray[j] += Number(targetInstancesString[i]);
    }
}

/* SERVICE */
const serviceChoice = flow.get('serviceChoice');

/* INPUT VALUE */
let inputValue = flow.get('inputValue');

let bacnetValue;

if (typeof inputValue === "boolean") {

    bacnetValue = {
        type: bacnet.ApplicationTag.BOOLEAN,
        value: inputValue
    };
}
else if (!isNaN(inputValue)) {

    bacnetValue = {
        type: bacnet.ApplicationTag.REAL,
        value: Number(inputValue)
    };
}

let results = [];

try {

    switch (serviceChoice) {

        /* ====================================================== */
        /* READ PROPERTY                                           */
        /* ====================================================== */

        case "serviceRead":

            address = {
                address: flow.get('ip') + ":" + flow.get('portDest'),
            };

            for (let i = 0; i <= j; i++) {

                const instance = targetInstancesArray[i];

                const value = await client.readProperty(
                    address,
                    {
                        type: objectType,
                        instance: instance
                    },
                    bacnet.PropertyIdentifier.PRESENT_VALUE
                );

                let result = {
                    object: objectType,
                    instance: instance,
                    value: value.values[0].value
                };

                results.push(result);

                msg.payload = result;
                node.send(msg);
            }

            msg.payload = {
                status: "✅ read successful"
            };

            node.send(msg);

        break;

        /* ====================================================== */
        /* READ PROPERTY MULTIPLE                                  */
        /* ====================================================== */

        case "serviceReadMultiple":

            address = {
                address: flow.get('ip') + ":" + flow.get('portDest'),
            };

            const requestArrayRead = [];

            for (let i = 0; i <= j; i++) {

                const instance = targetInstancesArray[i];

                requestArrayRead.push({
                    objectId: {
                        type: objectType,
                        instance: instance
                    },
                    properties: [{
                        id: bacnet.PropertyIdentifier.PRESENT_VALUE
                    }]
                });
            }

            const values = await client.readPropertyMultiple(
                address,
                requestArrayRead
            );

            msg.payload = values.values;
            node.send(msg);

            msg.payload = {
                status: "✅ multiple read successful"
            };

            node.send(msg);

        break;

        /* ====================================================== */
        /* WRITE PROPERTY                                          */
        /* ====================================================== */

        case "serviceWrite":

            address = {
                address: flow.get('ip') + ":" + flow.get('portDest'),
            };

            const instanceWrite = targetInstancesArray[0];

            await client.writeProperty(
                address,
                {
                    type: objectType,
                    instance: instanceWrite
                },
                bacnet.PropertyIdentifier.PRESENT_VALUE,
                [{
                    type: bacnetValue.type,
                    value: bacnetValue.value
                }],
                {
                    priority: 8
                }
            );

            let resultWrite = {
                object: objectType,
                instance: instanceWrite,
                writtenValue: inputValue
            };

            results.push(resultWrite);

            msg.payload = resultWrite;
            node.send(msg);

            msg.payload = {
                status: "✅ write successful"
            };

            node.send(msg);

        break;

        /* ====================================================== */
        /* WRITE PROPERTY MULTIPLE                                 */
        /* ====================================================== */

        case "serviceWriteMultiple":

            address = {
                address: flow.get('ip') + ":" + flow.get('portDest'),
            };

            const requestArrayWrite = [];

            for (let i = 0; i <= j; i++) {

                const instance = targetInstancesArray[i];

                requestArrayWrite.push({
                    objectId: {
                        type: objectType,
                        instance: instance
                    },
                    values: [{
                        property: {
                            id: bacnet.PropertyIdentifier.PRESENT_VALUE
                        },
                        value: [{
                            type: bacnetValue.type,
                            value: bacnetValue.value
                        }],
                        priority: 8
                    }]
                });
            }

            await client.writePropertyMultiple(
                address,
                requestArrayWrite
            );

            msg.payload = {
                status: "✅ multiple write successful"
            };

            node.send(msg);

        break;

case "whoIs":

    const discoveryMs = 5000;
    results = [];

    const onIAm = (device) => {

        try {

            node.warn("RAW I-AM: " + JSON.stringify(device));

            const result = {
                deviceId:
                    device.payload?.deviceId,

                address:
                    device.header?.sender?.address,

                port:
                    device.header?.sender?.port,

                maxApdu:
                    device.payload?.maxApdu,

                segmentation:
                    device.payload?.segmentation,

                vendorId:
                    device.payload?.vendorId
            };

            results.push(result);

            node.warn("DEVICE ADDED: " + JSON.stringify(result));

        }
        catch (err) {

            node.error("I-Am parse error: " + err.message);
        }
    };

    client.on('iAm', onIAm);

    node.warn("Sending WHO-IS to " + flow.get('ipBroadcast'));

    client.whoIs();

    setTimeout(() => {

        client.removeListener('iAm', onIAm);

        node.send({
            topic: "✅ who-is successful (" + results.length + " device(s))",
            payload: results
        });

        client.close();

    }, discoveryMs);

    return;
    }
}
catch (err) {

    node.error("Erreur BACnet: " + err);

